import React, { useCallback, useState } from 'react'
// import { DisplayCircleIcon, Row } from '../../../../../commonStyle/index.style'
import { Button, CustomText, Modal } from '../../../../../components'
import AutoSearchModal from '../../../../../components/AutoSearchModal'
import NumericInput from '../../../../../components/NumericInput'
// import Switch from '../../../../../components/Switch'
import TitleError from '../../../../../components/TitleError'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
// import { INFO } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { CoinsuranceFormStyle, PolicyProviderFormStyle } from './index.style'

function PolicyProviderForm ({
  resetErrorsKey,
  preFilledData,
  providerAutoRef,
  getProviderListData,
  getPolicySectionData,
  manualFleetFormErrors,
  productCode,
  getAllProviderRequest,
  errorField,
  providerCode
}) {
  const emptyProvider = {
    code: '',
    role: '',
    share_percent: 0,
    referral: 'INTERNAL',
    tnc_doc_url: '',
    provider_data: {}
  }
  // const [isCoinsurance, setIsCoinsurance] = useState(preFilledData.isCoinsurance || false)
  const isCoinsurance = false
  const [showInfoModal, setShowInfoModal] = useState(false)

  const [coinsuranceValues, setCoinsuranceValues] = useState(isCoinsurance && preFilledData?.providerData
    ? preFilledData?.providerData.length > 1
      ? preFilledData?.providerData
      : preFilledData?.providerData[0].role === 'LEADER'
        ? [preFilledData?.providerData[0], { ...emptyProvider }]
        : [{ ...emptyProvider }, preFilledData?.providerData[0]]
    : [{ ...emptyProvider }, { ...emptyProvider }]
  )

  const handlePreClicked = useCallback(() => {
    if (!getProviderListData.length) {
      getAllProviderRequest({
        query: {
          product_code: productCode,
          blacklist: 'offline',
          active_online_only: 'false',
          prov_pg_code: providerCode
        }
      })
    }
  }, [productCode, getAllProviderRequest, getProviderListData, providerCode])

  const handleSelectProvider = (provider, value, index) => {
    if (value || provider) {
      resetErrorsKey('providerData')
    }
    if (isCoinsurance && value) {
      const newFormValues = [...coinsuranceValues]
      newFormValues[index].code = provider
      newFormValues[index].role = index === 0 ? 'LEADER' : 'MEMBER'
      newFormValues[index].provider_data = value
      newFormValues[index].share_percent = 0
      setCoinsuranceValues(newFormValues)
      getPolicySectionData('providerData', newFormValues.filter(data => data.code && data.code !== ''))
    } else {
      getPolicySectionData('providerData', provider)
      setCoinsuranceValues([{ ...emptyProvider }])
    }
    getPolicySectionData('isCoinsurance', isCoinsurance)
  }

  const handleInputChange = (value, index) => {
    if (value) {
      resetErrorsKey('providerData')
    }
    if (isCoinsurance) {
      const newFormValues = [...coinsuranceValues]
      newFormValues[index].share_percent = value || 0
      setCoinsuranceValues(newFormValues)
      getPolicySectionData('providerData', coinsuranceValues.filter(data => data.code && data.code !== ''))
      getPolicySectionData('isCoinsurance', isCoinsurance)
    }
  }

  const addProviderMember = () => {
    setCoinsuranceValues([...coinsuranceValues, { ...emptyProvider }])
  }

  const removeProviderMember = useCallback((index) => {
    const newFormValues = [...coinsuranceValues]
    newFormValues.splice(index, 1)
    setCoinsuranceValues(newFormValues)
    getPolicySectionData('providerData', newFormValues)
  }, [coinsuranceValues, getPolicySectionData])

  // const handleToogle = (value) => {
  //   setIsCoinsurance(value)
  //   setCoinsuranceValues([{ ...emptyProvider }, { ...emptyProvider }])
  //   getPolicySectionData('providerData', !value ? '' : coinsuranceValues)
  //   getPolicySectionData('isCoinsurance', value)
  // }

  return (
    <PolicyProviderFormStyle>
      {/* <Row align='center' justify='space-between' className='activate-coinsurance'>
        <CustomText
          color={AgentColorPallette.regular}
          size='14px'
          weight={400}
          className='activate-coinsurance-text-box'
        >
          <DisplayCircleIcon width='18px' height='18px' onClick={() => setShowInfoModal(true)}>
            <img src={INFO} alt='' />
          </DisplayCircleIcon>
          <span className='activate-coinsurance-text'>{LANG_STRINGS.activateCoinsurance}</span>
        </CustomText>
        <Switch
          onChange={() => handleToogle(!isCoinsurance)}
          id='addons'
          isChecked={isCoinsurance}
          className='justify-self'
        />
      </Row> */}
      {
        !isCoinsurance
          ? (
            <>
              <TitleError
                title={LANG_STRINGS.insuranceProviderNew}
                error={manualFleetFormErrors.providerData ? LANG_STRINGS.required : ''}
                required
              />
              <AutoSearchModal
                data={getProviderListData}
                name='providerData'
                errorField={errorField}
                placeholder={LANG_STRINGS.select}
                title={LANG_STRINGS.insuranceProviderNew}
                id='auto_suggest_providers'
                displayKey='name'
                subTitle={LANG_STRINGS.maximumThree}
                dataKey='code'
                onSelect={handleSelectProvider}
                isMultiple
                defaultProviders={!preFilledData.isCoinsurance && preFilledData.providerData}
                maxSelectCount={3}
                titleForMultiple={LANG_STRINGS.selectedProviders}
                className='auto-search-codes'
                ref={providerAutoRef}
                handlePreClicked={handlePreClicked}
              />
            </>
          )
          : (
            <CoinsuranceFormStyle>
              {coinsuranceValues?.map((data, index) => (
                <div key={data.code || index} className='coinsurance-row'>
                  <div className='coinsurance-provider-field'>
                    <TitleError
                      title={index === 0 ? LANG_STRINGS.leaderProvider : LANG_STRINGS.memberProvider}
                      error={manualFleetFormErrors.providerData ? LANG_STRINGS.required : ''}
                    />
                    <AutoSearchModal
                      data={getProviderListData.filter((provider) => {
                        return !coinsuranceValues.find((innerProvider, innerIndex) => {
                          return innerIndex !== index && provider.code === innerProvider.code
                        })
                      })}
                      name='providerData'
                      errorField={errorField}
                      placeholder={LANG_STRINGS.select}
                      title={LANG_STRINGS.insuranceProviderNew}
                      id='auto_suggest_providers'
                      displayKey='name'
                      dataKey='code'
                      index={index}
                      onSelect={handleSelectProvider}
                      isOtherData
                      defaultValue={data.code}
                      titleForMultiple={LANG_STRINGS.selectedProviders}
                      className='auto-search-codes'
                      ref={providerAutoRef}
                      handlePreClicked={handlePreClicked}
                    />
                  </div>
                  <div className='coinsurance-provider-share'>
                    <TitleError
                      title={LANG_STRINGS.sharePercent}
                      error={manualFleetFormErrors.providerData ? LANG_STRINGS.required : ''}
                    />
                    <div className='input-container'>
                      {coinsuranceValues.length > 2 && index > 0 &&
                        <Button className='remove-provider' onClick={() => removeProviderMember(index)}>
                          x
                        </Button>}
                      <NumericInput
                        type='discount'
                        disabled={!data.code}
                        name='sharePercent'
                        id='policysharePercent'
                        className='number-box-shadow'
                        placeholder='0 %'
                        decimal='0'
                        onChange={(value) => handleInputChange(value, index)}
                        value={data?.share_percent}
                        defaultValue={data?.share_percent}
                      />
                    </div>
                  </div>
                </div>
              ))}
              <CustomText
                color={AgentColorPallette.fontDarkerGrey}
                size='13px'
                weight={400}
                className='coinsurance-info-text'
              >
                {LANG_STRINGS.coinsuranceInfoText}
              </CustomText>
              <div className='button-container'>
                <Button className='add-provider-btn' onClick={addProviderMember}>
                  {LANG_STRINGS.addNewMember}
                </Button>
              </div>

            </CoinsuranceFormStyle>
          )
      }
      {
        showInfoModal &&
          <Modal
            heading={LANG_STRINGS.information}
            isOpen={showInfoModal}
            onClose={() => setShowInfoModal(false)}
          >
            <CustomText
              color={AgentColorPallette.fontDarkerGrey}
              size='13px'
              weight={400}
              className='coinsurance-info-text'
            >
              {LANG_STRINGS.activateCoinsuranceModalText}
            </CustomText>
          </Modal>
      }
    </PolicyProviderFormStyle>
  )
}

export default PolicyProviderForm
