import { useCallback, useState } from 'react'
import { MitraCard, Row } from '../../../../../commonStyle/index.style'
import { Button, CustomText } from '../../../../../components'
import ButtonWithIcon from '../../../../../components/ButtonWithIcon'
import Collapsible from '../../../../../components/Collapsible'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { CAR_PROTECTION } from '../../../../../constants/pkgCode'
import { LANG_STRINGS } from '../../../../../lang'
import AddonsModal from '../AddonsModal'
import { PolicyOfflineAddonsStyle } from './index.style'

function PolicyOfflineAddons ({
  selectedAddons, selectedCustomAddons, preFilledAddons,
  preFilledCustomAddons, currencyType, paddingNotRequired = false
}) {
  const [addonsModal, setAddonsModal] = useState(false)

  const handleToggleModal = useCallback(() => {
    setAddonsModal(addonsModal => !addonsModal)
  }, [])

  const renderAddonTitleCheck = useCallback((addon) => (
    <Row align='center' justify='space-between'>
      <CustomText
        color={AgentColorPallette.fontDarkerGrey}
        size='10px'
      >
        {
          addon.add_on_name
        }
      </CustomText>
      <CustomText color={AgentColorPallette.green}>
        <i className='fa fa-check' />
      </CustomText>
    </Row>
  ), [])

  const renderSelectedAddonsList = useCallback(() => {
    const addonsMap = []
    let addonsLength = Object.keys(selectedAddons).length
    for (const categoryKey in selectedAddons) {
      const categoryItems = selectedAddons[categoryKey]
      addonsLength -= 1
      const item = (
        <Collapsible
          header={categoryKey}
          bodyPadding='2px 0'
          isOpen
          className='addons-collapsible-header'
        >
          {
            (function () {
              const itemsMap = []
              for (const addonKey in categoryItems) {
                const addon = categoryItems[addonKey]
                const categoryElement = renderAddonTitleCheck(addon)
                itemsMap.push(categoryElement)
              }
              return itemsMap
            })()
          }
        </Collapsible>
      )
      addonsMap.push(item)
      if (addonsLength !== 0) {
        addonsMap.push(<div className='separator-line' />)
      }
    }
    if (selectedCustomAddons?.custom_add_on?.length) {
      const customAddonMaps = []
      for (let index = 0; index < selectedCustomAddons.custom_add_on.length; index++) {
        const addon = selectedCustomAddons.custom_add_on[index]
        customAddonMaps.push(renderAddonTitleCheck(addon))
      }
      const CustomAddonCollapsible = (
        <Collapsible
          header={LANG_STRINGS.otherProtection}
          bodyPadding='2px 0'
          isOpen
          className='addons-collapsible-header'
        >
          {customAddonMaps}
        </Collapsible>
      )
      if (addonsMap.length) {
        addonsMap.push(<div className='separator-line' />)
      }
      addonsMap.push(CustomAddonCollapsible)
    }
    return addonsMap
  }, [selectedAddons, selectedCustomAddons, renderAddonTitleCheck])

  return (
    <PolicyOfflineAddonsStyle paddingNotRequired={paddingNotRequired}>
      <ButtonWithIcon
        text={LANG_STRINGS.packageAddons}
        onClick={handleToggleModal}
        isArrowButton
      />
      <CustomText
        color={AgentColorPallette.fontDarkerGrey}
        size='11px'
        top='4px'
        bottom={Object.keys(selectedAddons)?.length ? '16px' : '0'}
      >
        {LANG_STRINGS.continueToNextStepIfNoPackages}
      </CustomText>
      {
        !!(!!Object.keys(selectedAddons)?.length || (!!Object.keys(selectedCustomAddons)?.length && selectedCustomAddons?.custom_add_on?.length)) &&
        (
          <>
            <Row align='center' justify='space-between'>
              <CustomText
                color={AgentColorPallette.black}
                size='16px'
                weight={800}
              >
                {LANG_STRINGS.additionalPackageList}
              </CustomText>
              <Button
                textColor={AgentColorPallette.black}
                backgroundColor={AgentColorPallette.primary}
                handleClick={handleToggleModal}
                width='auto'
                className='offline-edit-policy'
              >
                {LANG_STRINGS.change}
              </Button>
            </Row>
            <MitraCard width='auto' bottom='0'>
              {renderSelectedAddonsList()}
            </MitraCard>
          </>
        )
      }
      {
        addonsModal && (
          <AddonsModal
            showModal={addonsModal}
            productCode={CAR_PROTECTION}
            onClose={handleToggleModal}
            preFilledAddons={preFilledAddons}
            preFilledCustomAddons={preFilledCustomAddons}
            currencyType={currencyType}
            isAllAddons
            hidePremium
          />
        )
      }
    </PolicyOfflineAddonsStyle>
  )
}

export default PolicyOfflineAddons
