import { useCallback, useState, useRef, useEffect } from 'react'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import PolicyAddons from '../../../../../../components/PolicyAddons'
import { updateLoader, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { CustomText } from '../../../../../../components'
import { LANG_STRINGS } from '../../../../../../lang'
import { PolicyAddonsContainerStyle } from './index.style'
import { CALCULATOR_GOLD } from '../../../../../../images'
import { BottomActionContainerStyle } from '../../../../../../commonStyle/index.style'
import isEmpty from 'lodash/isEmpty'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import CircularLoader from '../../../../../../components/CircularLoader'
import { useSetPolicyState } from '../../../state/hooks/usePolicyState'

function AddonsContainer ({
  history, onClose, isAllAddons, productCode,
  preFilledAddons, preFilledCustomAddons, hidePremium,
  currencyType
}) {
  const [{
    CALCULATE_ADDON_PREMIUM_LOADER, GET_PROVIDER_ADDONS_LOADER,
    GET_ALL_ADDONS_LOADER
  }, dispatchLoader] = useLoaderContextValue()

  const that = useRef({
    ...(preFilledAddons || {})
  })
  const customAddonRef = useRef({
    custom_add_on: preFilledCustomAddons || []
  })
  const [btnDisabled, setBtnDisable] = useState(true)
  const updatePolicyState = useSetPolicyState()

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_PROVIDER_ADDONS_LOADER: undefined,
        CALCULATE_ADDON_PREMIUM_LOADER: undefined,
        GET_ALL_ADDONS_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const handleChangesInAddon = useCallback((addonData) => {
    // save the addon data on that ref
    if (addonData?.custom_add_on) {
      customAddonRef.current = addonData
    } else {
      that.current = addonData
    }
    const customAddonLength = customAddonRef.current && !!Object.keys(customAddonRef.current).length
    const addonLength = Object.keys(that.current).length
    if ((addonLength || customAddonLength) && btnDisabled) {
      setTimeout(() => {
        setBtnDisable(false)
      }, 50)
    } else if (!addonLength && !customAddonLength) {
      setTimeout(() => {
        setBtnDisable(true)
      }, 50)
    }
  }, [btnDisabled])

  const validateCustomAddons = useCallback((customAddons = []) => {
    const customError = {}
    customAddons.forEach((item) => {
      if (!item.add_on_name || !item.add_on_description) {
        customError[item.key] = {
          add_on_name: !item.add_on_name,
          add_on_description: !item.add_on_description
        }
      }
    })
    return customError
  }, [])

  const handleSave = useCallback(() => {
    // history application data to review and data
    let isAddonsData = false
    for (const key in that.current) {
      const addons = that.current[key]
      if (!isEmpty(addons) && !isAddonsData) {
        isAddonsData = true
        break
      }
    }
    if (customAddonRef.current.custom_add_on && customAddonRef.current.custom_add_on.length) {
      const error = validateCustomAddons(customAddonRef.current.custom_add_on)
      updatePolicyState({
        customAddonError: {
          ...error
        }
      })
      if (!isEmpty(error)) return null
    }
    if (updatePolicyState) {
      updatePolicyState({
        addons: {
          ...that.current
        },
        customAddons: customAddonRef.current
      })
    }
    if (onClose) {
      onClose()
      return
    }
    history.push({
      pathname: '/car-protection/fleet-policy/order'
    })
  }, [history, onClose, updatePolicyState, validateCustomAddons])

  return (
    <PolicyAddonsContainerStyle>
      <CircularLoader
        className={(GET_ALL_ADDONS_LOADER || GET_PROVIDER_ADDONS_LOADER || CALCULATE_ADDON_PREMIUM_LOADER) ? 'addons-loader' : ''}
        isLoading={GET_PROVIDER_ADDONS_LOADER || CALCULATE_ADDON_PREMIUM_LOADER || GET_ALL_ADDONS_LOADER}
      >
        <CustomText color={AgentColorPallette.darkCharcoal} bottom='18px'>
          {LANG_STRINGS.pleaseAddProtectionBelow}
        </CustomText>
        <PolicyAddons
          productId={productCode}
          onChangeAddon={handleChangesInAddon}
          isAllAddons={isAllAddons}
          preFilledAddons={preFilledAddons}
          preFilledCustomAddons={preFilledCustomAddons}
          hidePremium={hidePremium}
          currencyType={currencyType}
          isCustomAddon
          isMVProduct
        />
        <BottomActionContainerStyle padding='0'>
          <ButtonWithIcon
            text={LANG_STRINGS.reviewChanges}
            icon={CALCULATOR_GOLD}
            iconRight
            className='bottom-btn'
            disabled={btnDisabled}
            onClick={handleSave}
          />
        </BottomActionContainerStyle>
      </CircularLoader>
    </PolicyAddonsContainerStyle>
  )
}

export default AddonsContainer
