import { useRef, useState, useCallback } from 'react'
import { Row } from '../../../../../commonStyle/index.style'
import { Button, CustomText, InnerInput } from '../../../../../components'
import CustomCheckbox from '../../../../../components/CustomCheckbox'
import NumericInput from '../../../../../components/NumericInput'
import TitleError from '../../../../../components/TitleError'
import VerticalRadioGroup from '../../../../../components/VerticalRadioGroup'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { CLOSE_ICON } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { ACCESSORY_TYPE } from '../../../Application/constants'
import { APPLICATION_LANG } from '../../../Application/lang'
import { PolicyModificationStyle } from './index.style'

function PolicyModification ({
  maxAmount, defaultData = [], errorObj = {}, totalSumInsured,
  onChangeAccessories = () => {}, resetErrorsKey = () => {}, paddingNotRequired = false,
  currencyType = {}
}) {
  const [isModificationSelect, setModificationSelect] = useState(!!defaultData.length || false)
  const [accessories, setAccessories] = useState(isModificationSelect ? defaultData : [
    {
      key: 'accessories1',
      sum_insured: '',
      accessory_type: 'standard'
    }
  ])
  const [showAddBtn, setShowAddBtn] = useState(true)
  const that = useRef({
    newAccessory: 1,
    totalSumInsured: totalSumInsured || 0
  })

  const handleChangeAccessories = useCallback((e, index) => {
    resetErrorsKey(`accessory${index}`)
    accessories[index].name = e.target.value
    onChangeAccessories({
      accessories,
      isModificationChecked: isModificationSelect,
      totalSumInsured: that.current.totalSumInsured
    })
    setAccessories([...accessories])
  }, [onChangeAccessories, resetErrorsKey, isModificationSelect, accessories])

  const handleCheckbox = useCallback(() => {
    setModificationSelect(isSelect => {
      const newIsSelect = !isSelect
      const initData = {
        accessories: [
          {
            key: 'accessories1',
            sum_insured: '',
            accessory_type: 'standard'
          }
        ],
        showAddBtn: true,
        totalSumInsured: 0
      }
      onChangeAccessories({
        ...initData,
        isModificationChecked: newIsSelect,
        accessories: newIsSelect ? initData.accessories : []
      })
      setAccessories(newIsSelect ? initData.accessories : [])
      return newIsSelect
    })
  }, [onChangeAccessories])

  const handleRadioChange = useCallback((accessoryType, index) => {
    // update the accessory with respect to index
    accessories[index].accessory_type = accessoryType.code
    const initialSumInsured = accessories[index].sum_insured || 0
    if (accessoryType.code === 'non-standard') {
      // only standard accessory have 10% limit of total_sum_insured
      // if sum_insured code change from standard to non-standard
      // then need to update the total_sum_insured
      that.current.totalSumInsured = that.current.totalSumInsured - initialSumInsured
    } else {
      that.current.totalSumInsured = that.current.totalSumInsured + initialSumInsured
    }

    const accessoriesMap = {
      accessories,
      isModificationChecked: isModificationSelect,
      totalSumInsured: that.current.totalSumInsured
    }
    setAccessories([...accessories])
    onChangeAccessories(accessoriesMap)
  }, [accessories, isModificationSelect, onChangeAccessories])

  const handleAddAccessories = useCallback(() => {
    if (accessories.length < 15) {
      accessories.push({
        key: `accessories${++that.current.newAccessory}`,
        accessory_type: 'standard'
      })
      setAccessories([...accessories])
      setShowAddBtn(accessories.length < 15)
      onChangeAccessories({
        accessories,
        isModificationChecked: isModificationSelect,
        totalSumInsured: that.current.totalSumInsured
      })
    }
  }, [accessories, onChangeAccessories, isModificationSelect])

  const handleChangeSumInsured = useCallback((data, index) => {
    resetErrorsKey(`accessory${index}`)
    const currentAccessoryType = accessories[index].accessory_type
    if (currentAccessoryType === 'standard') {
      // only standard accessory have 10% limit of total_sum_insured
      const initialSumInsured = accessories[index].sum_insured || 0
      that.current.totalSumInsured = that.current.totalSumInsured + Number(data) - initialSumInsured
    }
    accessories[index].sum_insured = data && Number(data)
    setAccessories([...accessories])
    onChangeAccessories({
      accessories,
      isModificationChecked: isModificationSelect,
      totalSumInsured: that.current.totalSumInsured
    })
  }, [accessories, isModificationSelect, onChangeAccessories, resetErrorsKey])

  const removeAccessoryForm = useCallback((index) => {
    // remove the selected index from the array
    const removedAccessory = accessories[index]
    if (removedAccessory.accessory_type === 'standard') {
      that.current.totalSumInsured = that.current.totalSumInsured - (removedAccessory.sum_insured || 0)
    }
    accessories.splice(index, 1)
    setAccessories([...accessories])
    onChangeAccessories({
      accessories,
      isModificationChecked: isModificationSelect,
      totalSumInsured: that.current.totalSumInsured
    })
    // Reset errors for remaining accessories to prevent index shifting issues
    for (let i = 0; i < accessories.length; i++) {
      resetErrorsKey(`accessory${i}`)
    }
  }, [accessories, onChangeAccessories, isModificationSelect, resetErrorsKey])

  const renderStandardSection = useCallback((item, index) => {
    // here render the radio button
    return (
      <>
        <TitleError
          title={LANG_STRINGS.accessoriesType}
          required
        />
        <Row align='center' justify='space-between'>
          {
            ACCESSORY_TYPE.map(accessory => (
              <VerticalRadioGroup
                key={`${accessory.type}_${item.key}`}
                data={accessory}
                id={`${accessory.type}_${item.key}`}
                selected={item.accessory_type}
                label={
                  <CustomText
                    size='12px'
                    color={AgentColorPallette.black}
                    weight={700}
                    onClick={() => handleRadioChange(accessory, index)}
                  >
                    {accessory.name}
                  </CustomText>
                }
                name={`${accessory.type}_${item.key}`}
                className='accessory-type-card'
                onClick={() => handleRadioChange(accessory, index)}
              />
            ))
          }
        </Row>
      </>
    )
  }, [handleRadioChange])
  return (
    <PolicyModificationStyle paddingNotRequired={paddingNotRequired}>
      <Row align='center' justify='space-between' className='modification-button'>
        <CustomText color={AgentColorPallette.goldDarker} weight={700} size='14px'>
          {LANG_STRINGS.vehicleModification}
        </CustomText>
        <CustomCheckbox
          isChecked={isModificationSelect}
          onChange={handleCheckbox}
          name='vehicleModifications'
          id='vehicleModificationsOffline'
          color={AgentColorPallette.black}
        />
      </Row>
      <CustomText color={AgentColorPallette.fontDarkerGrey} size='11px' top='4px'>
        {LANG_STRINGS.continueToNextStepIfNoModification}
      </CustomText>
      <div>
        {
          isModificationSelect && accessories.map((accessory, index) => (
            <div className='accessories' key={accessory.key}>
              {
                accessories.length > 1 &&
                  <img
                    src={CLOSE_ICON}
                    alt='close-icon'
                    className='close-icon-image'
                    onClick={() => removeAccessoryForm(index)}
                  />
              }
              {
                renderStandardSection(accessory, index)
              }
                <TitleError
                  title={LANG_STRINGS.accessoriesName}
                  required
                  error={errorObj[`${accessory.key}`] && errorObj[`${accessory.key}`].name && LANG_STRINGS.required}
                />
                <InnerInput
                  placeholder={APPLICATION_LANG.masukanNamaAksesoris}
                  name='name'
                  defaultValue={accessory.name}
                  errorField={errorObj[`${accessory.key}`] && errorObj[`${accessory.key}`].name && LANG_STRINGS.required ? 'name' : ''}
                  onChange={e => handleChangeAccessories(e, index)}
                  displayBorder
                />
                <TitleError
                  title={LANG_STRINGS.accessoriesPrice}
                  required
                  error={errorObj[`${accessory.key}`] && errorObj[`${accessory.key}`].sum_insured && LANG_STRINGS.required}
                />
                <NumericInput
                  errorField={errorObj[`${accessory.key}`] && errorObj[`${accessory.key}`].sum_insured && LANG_STRINGS.required ? 'accessoryAmount' : ''}
                  type='amount'
                  name='accessoryAmount'
                  className='number-box-shadow'
                  displayBorder
                  defaultValue={accessory.sum_insured}
                  onChange={(data) => handleChangeSumInsured(data, index)}
                  placeholder={LANG_STRINGS.enterPriceAccessories}
                  amountPrefix={`${currencyType?.currency_symbol}`}
                  currencySymbol={currencyType?.currency_symbol}
                />
            </div>
          ))
        }
        {
          isModificationSelect && showAddBtn && (
            <Button
              className='add-more-button'
              onClick={handleAddAccessories}
            >
              {LANG_STRINGS.add}
            </Button>
          )
        }
      </div>
    </PolicyModificationStyle>
  )
}

export default PolicyModification
